import shutil
import subprocess
from pathlib import Path
from agents import function_tool


def _prune_applied(applied_dir: Path, keep: int = 100) -> None:
    # Keep only the most recent migrations in the applied directory
    files = sorted(applied_dir.glob('*.sql'), key=lambda f: f.stat().st_mtime)
    for old in files[:-keep]:
        old.unlink()


@function_tool
def archive_and_run_migration(migration_file: str, db_path: str, pending_dir: str, applied_dir: str) -> str:
    src = Path(pending_dir) / migration_file
    dst_dir = Path(applied_dir)
    dst = dst_dir / migration_file
    if not src.is_file():
        return 'error: migration not found: %s' % src
    if not Path(db_path).is_file():
        return 'error: database not found: %s' % db_path
    if dst.exists():
        return 'error: already applied: %s' % dst
    dst_dir.mkdir(parents=True, exist_ok=True)
    moved = shutil.move(str(src), str(dst))
    try:
        p = subprocess.run(['sqlite3', db_path, '.read %s' % moved], capture_output=True, text=True, timeout=300)
    except subprocess.TimeoutExpired:
        return 'error: migration timed out, file moved to %s' % moved
    out = p.stdout.strip()
    err = p.stderr.strip()
    if p.returncode != 0:
        return 'failed (exit %d), file moved to %s: %s' % (p.returncode, moved, err)
    _prune_applied(dst_dir)
    return 'ok, moved to %s. output: %s' % (moved, out or '(none)')
